import type { BankQuestion } from "@/lib/bank";

/** Synonyms, Antonyms and One-Word Substitution (English): 173 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"eng-vocabulary-1","question":"Choose the synonym of “Abundant”.","options":["Scarce","Plentiful","Rare","Empty"],"answer":1,"explanation":"Abundant means existing in large quantities, i.e., plentiful.","difficulty":"easy"},
  {"id":"eng-vocabulary-2","question":"Choose the antonym of “Ancient”.","options":["Old","Modern","Antique","Historic"],"answer":1,"explanation":"Ancient means very old; its opposite is modern.","difficulty":"easy"},
  {"id":"eng-vocabulary-3","question":"Choose the antonym of “Benevolent”.","options":["Kind","Generous","Malevolent","Charitable"],"answer":2,"explanation":"Benevolent means well-meaning; malevolent means wishing harm.","difficulty":"moderate"},
  {"id":"eng-vocabulary-4","question":"One who knows everything is called:","options":["Omnipotent","Omnipresent","Omniscient","Omnivorous"],"answer":2,"explanation":"Omniscient = all-knowing; omnipotent = all-powerful; omnipresent = present everywhere.","difficulty":"moderate"},
  {"id":"eng-vocabulary-5","question":"One who looks at the bright side of things is called:","options":["Pessimist","Optimist","Realist","Altruist"],"answer":1,"explanation":"An optimist expects the best; a pessimist expects the worst.","difficulty":"moderate"},
  {"id":"eng-vocabulary-6","question":"Choose the synonym of “Ephemeral”.","options":["Eternal","Short-lived","Heavy","Bright"],"answer":1,"explanation":"Ephemeral means lasting for a very short time.","difficulty":"hard"},
  {"id":"eng-vocabulary-7","question":"A person who can speak many languages is called a:","options":["Linguist","Polyglot","Orator","Philologist"],"answer":1,"explanation":"A polyglot knows and uses several languages; a linguist studies language scientifically.","difficulty":"hard"},
  {"id":"eng-vocabulary-8","question":"Choose the antonym of “Verbose”.","options":["Talkative","Concise","Lengthy","Loud"],"answer":1,"explanation":"Verbose means using more words than needed; concise means brief and to the point.","difficulty":"hard"},
  {"id":"eng-vocabulary-9","question":"Choose the synonym of “Obsequious”.","options":["Arrogant","Servile","Honest","Lazy"],"answer":1,"explanation":"Obsequious means excessively eager to please or obey, i.e., servile.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-10","question":"A government by the wealthy is called:","options":["Oligarchy","Plutocracy","Theocracy","Autocracy"],"answer":1,"explanation":"Plutocracy = rule by the rich; oligarchy = rule by a few; theocracy = rule by religious leaders.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-11","question":"Choose the antonym of “Garrulous”.","options":["Talkative","Taciturn","Friendly","Angry"],"answer":1,"explanation":"Garrulous means excessively talkative; taciturn means reserved and saying little.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-12","question":"Choose the antonym of “Abundant”.","options":["Plentiful","Scarce","Ample","Rich"],"answer":1,"explanation":"Abundant means plentiful; scarce is its opposite.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"eng-vocabulary-13","question":"Choose the synonym of “Candid”.","options":["Secretive","Frank","Clever","Rude"],"answer":1,"explanation":"Candid means frank and honest.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-14","question":"One word for “a person who can speak many languages”:","options":["Linguist","Polyglot","Orator","Bilingual"],"answer":1,"explanation":"A polyglot knows several languages; a linguist studies language.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-15","question":"The idiom “to beat around the bush” means:","options":["To hunt in a forest","To avoid the main point","To work very hard","To lose one’s way"],"answer":1,"explanation":"It means to talk indirectly and avoid the real issue.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-16","question":"Choose the antonym of “Ephemeral”.","options":["Brief","Eternal","Fleeting","Momentary"],"answer":1,"explanation":"Ephemeral means short-lived; eternal is its opposite.","difficulty":"hard","source":"SSC CGL · SBI PO"},
  {"id":"eng-vocabulary-17","question":"One word for “a government by the rich”:","options":["Oligarchy","Plutocracy","Autocracy","Theocracy"],"answer":1,"explanation":"Plutocracy is rule by the wealthy; oligarchy is rule by a few.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-vocabulary-18","question":"Choose the synonym of “Ubiquitous”.","options":["Rare","Omnipresent","Unique","Hidden"],"answer":1,"explanation":"Ubiquitous means found everywhere.","difficulty":"hard"},
  {"id":"eng-vocabulary-19","question":"Choose the antonym of “Laconic”.","options":["Brief","Verbose","Terse","Curt"],"answer":1,"explanation":"Laconic means using very few words; verbose is the opposite.","difficulty":"hard"},
  {"id":"eng-vocabulary-20","question":"One word for “a person who bears pain or hardship without showing feelings”:","options":["Stoic","Hedonist","Cynic","Sceptic"],"answer":0,"explanation":"A stoic endures without complaint; a hedonist seeks pleasure.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-21","question":"The idiom “to cut the Gordian knot” means:","options":["To break a promise","To solve a hard problem by a bold, direct action","To end a friendship","To waste time on small details"],"answer":1,"explanation":"From the legend of Alexander slicing through a knot nobody could untie.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-22","question":"Choose the synonym of “Obfuscate”.","options":["Clarify","Obscure","Illuminate","Simplify"],"answer":1,"explanation":"To obfuscate is to make something unclear on purpose.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-23","question":"Choose the antonym of “Recalcitrant”.","options":["Obstinate","Compliant","Defiant","Unruly"],"answer":1,"explanation":"Recalcitrant means stubbornly disobedient; compliant is the opposite.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-24","question":"Choose the word nearest in meaning to OBSEQUIOUS.","options":["Servile","Obstinate","Obscure","Generous"],"answer":0,"explanation":"Obsequious means too eager to please or obey, i.e. servile.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-25","question":"Choose the word opposite in meaning to EPHEMERAL.","options":["Transient","Perpetual","Fleeting","Brief"],"answer":1,"explanation":"Ephemeral means short-lived; the other three options are its synonyms.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-26","question":"One word for “a person who is indifferent to pleasure and pain”:","options":["Stoic","Hedonist","Cynic","Epicure"],"answer":0,"explanation":"A stoic endures pain and pleasure without showing feeling; a hedonist pursues pleasure.","difficulty":"very-hard"},
  {"id":"eng-vocabulary-27","question":"Choose the word nearest in meaning to PERFUNCTORY.","options":["Cursory","Thorough","Deliberate","Elaborate"],"answer":0,"explanation":"Perfunctory means done quickly and without real care or interest, i.e. cursory; the other three describe careful work.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-28","question":"Choose the word opposite in meaning to PARSIMONIOUS.","options":["Frugal","Munificent","Thrifty","Miserly"],"answer":1,"explanation":"Parsimonious means unwilling to spend money; munificent means very generous. Frugal, thrifty and miserly are all near-synonyms of the given word.","difficulty":"very-hard","source":"SSC CGL · SBI PO"},
  {"id":"eng-vocabulary-29","question":"Choose the synonym of “Brave”.","options":["Courageous","Timid","Cowardly","Weak"],"answer":0,"explanation":"Brave means showing courage; courageous is its synonym, while timid and cowardly are its opposites.","difficulty":"easy","source":"SSC GD · RRB Group D"},
  {"id":"eng-vocabulary-30","question":"Choose the antonym of “Generous”.","options":["Kind","Liberal","Stingy","Charitable"],"answer":2,"explanation":"Generous means giving freely; stingy (mean, unwilling to spend) is the opposite. Liberal and charitable are synonyms.","difficulty":"easy","source":"SSC GD · SSC CHSL"},
  {"id":"eng-vocabulary-31","question":"One word for “a place where bees are kept”:","options":["Aviary","Aquarium","Arboretum","Apiary"],"answer":3,"explanation":"An apiary is where bees (Latin apis) are kept. An aviary houses birds, an aquarium fish and an arboretum trees.","difficulty":"easy","source":"SSC CHSL · SSC CGL"},
  {"id":"eng-vocabulary-32","question":"Choose the synonym of “Meticulous”.","options":["Scrupulous","Hasty","Careless","Lazy"],"answer":0,"explanation":"Meticulous means very careful and precise about details; scrupulous is the closest. Careless is the antonym.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-33","question":"Choose the antonym of “Transparent”.","options":["Clear","Opaque","Lucid","Obvious"],"answer":1,"explanation":"Transparent means allowing light through or easy to see through; opaque means not letting light pass. Clear and lucid are synonyms.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"eng-vocabulary-34","question":"One word for “a person who is unable to pay his debts”:","options":["Insolvent","Solvent","Creditor","Debtor"],"answer":0,"explanation":"Insolvent is the person or firm unable to pay debts. A debtor merely owes money and may well be able to pay; a creditor is owed money.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-35","question":"The idiom “to bury the hatchet” means:","options":["To hide a weapon","To start a quarrel","To make peace","To dig a grave"],"answer":2,"explanation":"To bury the hatchet is to end a quarrel and become friendly again; the literal picture of burying a weapon is the trap.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-36","question":"One word for “the study of ancient remains and societies”:","options":["Anthropology","Geology","Palaeontology","Archaeology"],"answer":3,"explanation":"Archaeology studies ancient societies through their physical remains. Anthropology studies humankind generally, palaeontology fossils, geology the earth.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"eng-vocabulary-37","question":"Choose the synonym of “Lethargic”.","options":["Energetic","Sluggish","Alert","Agile"],"answer":1,"explanation":"Lethargic means lacking energy or enthusiasm; sluggish is its synonym. The other three options all describe liveliness.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-38","question":"Choose the synonym of “Taciturn”.","options":["Reserved","Talkative","Gloomy","Rude"],"answer":0,"explanation":"Taciturn means habitually saying little; reserved is nearest. Talkative is the antonym, and gloomy or rude describe mood, not speech.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-39","question":"Choose the antonym of “Prodigal”.","options":["Frugal","Lavish","Wasteful","Reckless"],"answer":0,"explanation":"Prodigal means wastefully extravagant (as in the prodigal son); frugal, careful with money, is the opposite. Lavish and wasteful are synonyms.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-vocabulary-40","question":"One word for “a person who hates mankind”:","options":["Philanthropist","Misogynist","Anthropologist","Misanthrope"],"answer":3,"explanation":"A misanthrope hates people in general. A misogynist hates women specifically, a philanthropist loves mankind and an anthropologist studies it.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-41","question":"The idiom “a wild goose chase” means:","options":["A hunting expedition","A futile search","A sudden journey","A noisy quarrel"],"answer":1,"explanation":"A wild goose chase is a hopeless, pointless pursuit of something that cannot be found.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-42","question":"Choose the word nearest in meaning to SANGUINE.","options":["Bloody","Pessimistic","Optimistic","Calm"],"answer":2,"explanation":"Sanguine means hopeful and confident about the future. Though it comes from the Latin for blood, 'bloody' is the etymological trap, not the meaning.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-43","question":"Choose the word opposite in meaning to OBSOLETE.","options":["Ancient","Current","Dormant","Outdated"],"answer":1,"explanation":"Obsolete means no longer in use or out of date; current (in present use) is the opposite. Outdated is a synonym.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-44","question":"One word for “a person who cannot be corrected or reformed”:","options":["Incredible","Indelible","Incorrigible","Infallible"],"answer":2,"explanation":"Incorrigible means beyond correction. Incredible is unbelievable, indelible cannot be erased, infallible never makes mistakes.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-vocabulary-45","question":"Fill in the blank with the most suitable word: The minister's ___ remarks about the flood victims drew sharp criticism.","options":["callus","candid","careful","callous"],"answer":3,"explanation":"Callous means insensitive and unfeeling, which is why the remarks were criticised. Callus (a patch of hard skin) is the homophone trap; candid or careful remarks would not invite criticism.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-46","question":"Choose the word nearest in meaning to EQUIVOCAL.","options":["Ambiguous","Equal","Clear","Honest"],"answer":0,"explanation":"Equivocal means open to more than one interpretation, deliberately vague. 'Equal' is a false friend from the spelling; clear and honest are near-opposites.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-47","question":"Choose the word nearest in meaning to PUSILLANIMOUS.","options":["Generous","Insignificant","Cowardly","Cheerful"],"answer":2,"explanation":"Pusillanimous means lacking courage, timid. The word's length tempts guesses like 'insignificant'; its root is Latin pusillus (very small) + animus (spirit).","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-48","question":"Choose the word opposite in meaning to NADIR.","options":["Bottom","Zenith","Depth","Abyss"],"answer":1,"explanation":"Nadir is the lowest point; zenith is the highest. The other three are synonyms of nadir, not antonyms.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-49","question":"One word for “an irrational fear of enclosed spaces”:","options":["Claustrophobia","Agoraphobia","Acrophobia","Xenophobia"],"answer":0,"explanation":"Claustrophobia is fear of confined spaces. Agoraphobia is fear of open or public places (the common confusion), acrophobia of heights, xenophobia of foreigners.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-vocabulary-50","question":"The idiom “to take something with a pinch of salt” means:","options":["To believe it fully","To accept it with some doubt","To add flavour to it","To criticise it harshly"],"answer":1,"explanation":"To take a statement with a pinch (or grain) of salt is to be sceptical about its truth, not to accept it wholesale.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-51","question":"Fill in the blank with the most suitable word: Despite his ___ manner, the professor was deeply respected by his students.","options":["affable","amiable","abrasive","agreeable"],"answer":2,"explanation":"'Despite' signals a contrast with being respected, so the manner must be unpleasant: abrasive (harsh, rude). Affable, amiable and agreeable all mean pleasant and would need 'because of', not 'despite'.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-52","question":"Choose the correctly spelt word to complete the sentence: The court's decision will have a ___ effect on future cases.","options":["salutory","salutary","salutery","saluatory"],"answer":1,"explanation":"Salutary (beneficial, though perhaps unwelcome) is spelt with -ary. The -ory ending is the usual misspelling by confusion with 'salutatory'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-vocabulary-53","question":"One word for “a person who believes that nothing can be known about the existence of God”:","options":["Atheist","Theist","Heretic","Agnostic"],"answer":3,"explanation":"An agnostic holds that God's existence cannot be known. An atheist positively denies God, a theist believes in God, and a heretic holds beliefs against accepted doctrine.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-54","question":"Which of the following pairs is NOT a pair of synonyms?","options":["Lucid – Clear","Candid – Frank","Docile – Stubborn","Mitigate – Alleviate"],"answer":2,"explanation":"Docile means easily taught or managed, the opposite of stubborn. Lucid/clear, candid/frank and mitigate/alleviate are all synonym pairs.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-55","question":"Choose the word opposite in meaning to AMELIORATE.","options":["Improve","Maintain","Worsen","Assist"],"answer":2,"explanation":"Ameliorate means to make better; worsen (aggravate) is its antonym. Improve is a synonym.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-vocabulary-56","question":"The idiom “to cut no ice” means:","options":["To fail to make an impression","To be very cold","To break a rule","To avoid a problem"],"answer":0,"explanation":"If an argument cuts no ice with someone, it has no effect on them. The literal reading about cold is the trap.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-vocabulary-57","question":"Choose the word nearest in meaning to VITUPERATIVE.","options":["Praising","Abusive","Lively","Vivid"],"answer":1,"explanation":"Vituperative means bitter and abusive in language. 'Lively' and 'vivid' are traps from the similar-looking root 'viv-'; praising is the opposite.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-vocabulary-58","question":"One word for “a disease that spreads across a whole country or the world”:","options":["Epidemic","Endemic","Sporadic","Pandemic"],"answer":3,"explanation":"A pandemic spreads over a whole country or the globe. An epidemic affects many people in one community at a time, an endemic disease is regularly found in a particular area, and sporadic means occurring occasionally.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id": "eng-vocabulary-59", "question": "Choose the synonym of “Diligent”.", "options": ["Lazy", "Hardworking", "Careless", "Clever"], "answer": 1, "explanation": "Diligent means showing steady, careful effort, i.e. hardworking. 'Clever' is about intelligence, not effort.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-vocabulary-60", "question": "Choose the antonym of “Expand”.", "options": ["Contract", "Enlarge", "Extend", "Explode"], "answer": 0, "explanation": "Expand means to grow larger; contract means to become smaller. Enlarge and extend are synonyms.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-vocabulary-61", "question": "Choose the synonym of “Prudent”.", "options": ["Reckless", "Proud", "Timid", "Judicious"], "answer": 3, "explanation": "Prudent means acting with care and good judgement, i.e. judicious. 'Proud' is a look-alike trap; 'reckless' is the opposite.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-62", "question": "Choose the antonym of “Hostile”.", "options": ["Aggressive", "Unfriendly", "Amicable", "Belligerent"], "answer": 2, "explanation": "Hostile means unfriendly or antagonistic; amicable means friendly. Aggressive and belligerent are near-synonyms.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-63", "question": "One word for “a person who walks in his sleep”:", "options": ["Insomniac", "Somnambulist", "Hypnotist", "Pedestrian"], "answer": 1, "explanation": "A somnambulist walks in sleep (Latin somnus = sleep, ambulare = walk). An insomniac cannot sleep at all.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-64", "question": "The idiom “to burn the midnight oil” means:", "options": ["To work or study late into the night", "To waste money", "To start a quarrel", "To finish work early"], "answer": 0, "explanation": "To burn the midnight oil is to stay up late working or studying, originally by lamplight.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-65", "question": "One word for “writing that cannot be read”:", "options": ["Ineligible", "Illiterate", "Invisible", "Illegible"], "answer": 3, "explanation": "Illegible means not clear enough to be read. Ineligible (not qualified) is the classic look-alike trap.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-66", "question": "Choose the synonym of “Cajole”.", "options": ["Threaten", "Scold", "Coax", "Ignore"], "answer": 2, "explanation": "To cajole is to persuade someone by flattery or gentle urging, i.e. to coax. Threatening is the opposite approach.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-67", "question": "Choose the antonym of “Ostentatious”.", "options": ["Showy", "Unpretentious", "Flamboyant", "Pompous"], "answer": 1, "explanation": "Ostentatious means showy and designed to impress; unpretentious means modest and simple. The other options are synonyms.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-68", "question": "One word for “a speech made without preparation”:", "options": ["Extempore", "Soliloquy", "Monologue", "Epilogue"], "answer": 0, "explanation": "An extempore speech is delivered without preparation. A soliloquy is speaking one's thoughts alone on stage; an epilogue is a closing section.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-69", "question": "The idiom “to be in the doldrums” means:", "options": ["To be in great danger", "To be very busy", "To be in debt", "To be in low spirits or inactive"], "answer": 3, "explanation": "The doldrums are calm equatorial waters where sailing ships stalled; being in the doldrums means feeling gloomy or stagnant.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-70", "question": "Choose the synonym of “Alacrity”.", "options": ["Reluctance", "Anxiety", "Eagerness", "Laziness"], "answer": 2, "explanation": "Alacrity means brisk, cheerful readiness, i.e. eagerness. Reluctance is the opposite.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-71", "question": "Choose the antonym of “Indolent”.", "options": ["Idle", "Industrious", "Insolent", "Sluggish"], "answer": 1, "explanation": "Indolent means lazy; industrious means hardworking. 'Insolent' (rude) is a look-alike; idle and sluggish are synonyms.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-72", "question": "One word for “the killing of one's own mother”:", "options": ["Matricide", "Patricide", "Fratricide", "Infanticide"], "answer": 0, "explanation": "Matricide (mater = mother) is killing one's mother. Patricide is killing the father, fratricide a brother, infanticide an infant.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-73", "question": "Choose the synonym of “Obdurate”.", "options": ["Obedient", "Obscure", "Remorseful", "Stubborn"], "answer": 3, "explanation": "Obdurate means stubbornly refusing to change one's opinion. 'Obedient' is the opposite, and 'obscure' only looks similar.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-74", "question": "Choose the antonym of “Truculent”.", "options": ["Aggressive", "Defiant", "Docile", "Belligerent"], "answer": 2, "explanation": "Truculent means eager to argue or fight; docile means meek and easily managed. The other three options are synonyms.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-75", "question": "One word for “an abnormal fear of water”:", "options": ["Acrophobia", "Hydrophobia", "Agoraphobia", "Xenophobia"], "answer": 1, "explanation": "Hydrophobia (hydro = water) is fear of water. Acrophobia is fear of heights, agoraphobia of open or crowded places, xenophobia of foreigners.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-76", "question": "The phrase “a Pyrrhic victory” means:", "options": ["A victory won at so great a cost that it is almost a defeat", "A victory won without a fight", "A victory won by deceit", "A narrow victory in the last moment"], "answer": 0, "explanation": "King Pyrrhus defeated Rome but lost so many men that the win was ruinous. A Pyrrhic victory costs the winner nearly as much as defeat.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-77", "question": "Choose the synonym of “Sycophant”.", "options": ["Critic", "Rebel", "Sympathiser", "Flatterer"], "answer": 3, "explanation": "A sycophant is someone who flatters powerful people for personal gain. 'Sympathiser' is a look-alike trap.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-78", "question": "Choose the antonym of “Ebullient”.", "options": ["Exuberant", "Effervescent", "Subdued", "Buoyant"], "answer": 2, "explanation": "Ebullient means cheerful and full of energy; subdued means quiet and low-spirited. The other three are synonyms.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-79", "question": "Which of the following pairs is NOT a pair of antonyms?", "options": ["Arid – Humid", "Abate – Subside", "Benign – Malignant", "Lethal – Harmless"], "answer": 1, "explanation": "Abate and subside both mean to become less intense, so they are synonyms. The other pairs are opposites.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-80", "question": "One word for “a person who studies the origin and history of words”:", "options": ["Etymologist", "Entomologist", "Philologist", "Lexicographer"], "answer": 0, "explanation": "An etymologist studies word origins. An entomologist studies insects (the classic trap), and a lexicographer compiles dictionaries.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-81", "question": "Fill in the blank with the most suitable word: The witness's ___ testimony, full of contradictions, was rejected by the court.", "options": ["cogent", "lucid", "compelling", "incoherent"], "answer": 3, "explanation": "Testimony full of contradictions is incoherent (lacking logical connection). Cogent, lucid and compelling would make the court accept it.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-82", "question": "The idiom “to have feet of clay” means:", "options": ["To be very slow", "To be firmly rooted", "To have a hidden weakness despite being admired", "To be humble"], "answer": 2, "explanation": "From the statue in the Book of Daniel with a gold head but clay feet: an admired person with a hidden flaw.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-83", "question": "Choose the synonym of “Recondite”.", "options": ["Reconciled", "Abstruse", "Recent", "Obvious"], "answer": 1, "explanation": "Recondite means little known and difficult to understand, i.e. abstruse. 'Obvious' is the opposite; the other two only look alike.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-84", "question": "Choose the synonym of “Feeble”.", "options": ["Weak", "Angry", "Quick", "Strong"], "answer": 0, "explanation": "Feeble means lacking strength, i.e. weak. Strong is its antonym.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-vocabulary-85", "question": "Choose the antonym of “Victory”.", "options": ["Success", "Defeat", "Conquest", "Triumph"], "answer": 1, "explanation": "The opposite of victory is defeat. Triumph, success and conquest are near-synonyms.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-vocabulary-86", "question": "One word for “a person who does not eat meat”:", "options": ["Herbivore", "Carnivore", "Vegan", "Vegetarian"], "answer": 3, "explanation": "A vegetarian does not eat meat. A vegan also avoids all animal products such as milk; herbivore is used for animals.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "eng-vocabulary-87", "question": "Choose the synonym of “Arduous”.", "options": ["Brief", "Easy", "Laborious", "Ardent"], "answer": 2, "explanation": "Arduous means needing great effort: laborious. Ardent (passionate) only looks similar.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-88", "question": "Choose the antonym of “Exonerate”.", "options": ["Absolve", "Incriminate", "Pardon", "Acquit"], "answer": 1, "explanation": "To exonerate is to clear someone of blame; to incriminate is to make them appear guilty. Acquit, absolve and pardon are close to exonerate.", "difficulty": "moderate", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-89", "question": "One word for “a person who studies or collects coins”:", "options": ["Numismatist", "Archivist", "Cartographer", "Philatelist"], "answer": 0, "explanation": "A numismatist collects or studies coins (and medals). A philatelist collects stamps.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-90", "question": "The idiom “to spill the beans” means:", "options": ["To make a mess", "To lose money", "To waste food", "To reveal a secret"], "answer": 3, "explanation": "To spill the beans is to let out secret information, often by accident.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "eng-vocabulary-91", "question": "One word for “a remedy for all diseases or problems”:", "options": ["Antidote", "Placebo", "Panacea", "Vaccine"], "answer": 2, "explanation": "A panacea is a cure-all. An antidote counters a particular poison; a placebo has no active ingredient.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-92", "question": "Choose the synonym of “Eminent”.", "options": ["Ordinary", "Imminent", "Distinguished", "Obscure"], "answer": 2, "explanation": "Eminent means famous and respected: distinguished. Imminent (about to happen) is a commonly confused word; obscure is the antonym.", "difficulty": "moderate", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-93", "question": "The idiom “to steal someone's thunder” means:", "options": ["To rob someone at night", "To lose one's temper", "To frighten someone", "To take the attention or credit someone else expected"], "answer": 3, "explanation": "To steal someone's thunder is to win the praise or attention another person was about to get, often by doing or saying their thing first.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-94", "question": "Choose the synonym of “Insipid”.", "options": ["Vivid", "Bland", "Spicy", "Insolent"], "answer": 1, "explanation": "Insipid means lacking flavour or interest: bland. Insolent (rude) is a look-alike trap; vivid is nearly opposite.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-95", "question": "Choose the antonym of “Gregarious”.", "options": ["Reclusive", "Talkative", "Friendly", "Sociable"], "answer": 0, "explanation": "Gregarious means fond of company. A reclusive person avoids others, so it is the antonym; the other three are close in meaning to gregarious.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-96", "question": "One word for “a speech or piece of writing praising someone, especially one who has just died”:", "options": ["Elegy", "Epitaph", "Eulogy", "Epilogue"], "answer": 2, "explanation": "A eulogy is a speech of praise, typically at a funeral. An elegy is a mournful poem, an epitaph is the inscription on a tomb and an epilogue ends a book.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-97", "question": "One word for “a word or phrase that reads the same backwards as forwards”:", "options": ["Palindrome", "Homonym", "Acronym", "Anagram"], "answer": 0, "explanation": "A palindrome reads the same both ways (madam, level). An anagram rearranges letters to form a new word.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-98", "question": "The idiom “to show the white feather” means:", "options": ["To surrender honourably", "To show cowardice", "To make peace", "To show off one's wealth"], "answer": 1, "explanation": "To show the white feather is to act in a cowardly way. Surrender is suggested by a white flag, which is the trap.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-99", "question": "Choose the synonym of “Mendacious”.", "options": ["Begging", "Repairing", "Generous", "Untruthful"], "answer": 3, "explanation": "Mendacious means given to telling lies: untruthful. 'Begging' confuses it with mendicant, and 'repairing' with mend.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-100", "question": "Choose the antonym of “Fastidious”.", "options": ["Fussy", "Undemanding", "Particular", "Meticulous"], "answer": 1, "explanation": "A fastidious person is hard to please and very attentive to detail. Undemanding is the opposite; meticulous, fussy and particular are near-synonyms.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-101", "question": "Choose the correctly spelt word for “government by unelected officials and red tape”.", "options": ["Bureaucracy", "Bureacracy", "Beurocracy", "Beaurocracy"], "answer": 0, "explanation": "The correct spelling is bureaucracy, from French bureau (desk) + -cracy (rule).", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-vocabulary-102", "question": "The phrase “a red herring” means:", "options": ["A dangerous person", "An unexpected profit", "A rare delicacy", "Something that misleads or distracts from the real issue"], "answer": 3, "explanation": "A red herring is a clue or point that draws attention away from the real question, as in a detective story. It has nothing to do with food in this use.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-103", "question": "One word for “favouritism shown by people in power to their relatives, especially in giving jobs”:", "options": ["Despotism", "Cronyism", "Nepotism", "Chauvinism"], "answer": 2, "explanation": "Nepotism is favouring relatives. Cronyism is favouring friends and associates, the closest trap; despotism is tyrannical rule.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-104", "question": "One word for “a position that gives pay or status but needs little or no work”:", "options": ["Honorarium", "Sinecure", "Sabbatical", "Stipend"], "answer": 1, "explanation": "A sinecure is a paid post with almost no duties. A stipend is a fixed allowance and an honorarium a fee for a service otherwise unpaid.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-105", "question": "Choose the word nearest in meaning to PERSPICACIOUS.", "options": ["Discerning", "Transparent", "Persistent", "Sweaty"], "answer": 0, "explanation": "Perspicacious means having keen insight: discerning or shrewd. 'Sweaty' plays on perspire and 'transparent' on perspicuous (clearly expressed), both traps.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-106", "question": "Choose the word opposite in meaning to MAGNANIMOUS.", "options": ["Noble", "Generous", "Petty", "Large"], "answer": 2, "explanation": "Magnanimous means generous in forgiving, big-hearted. Its opposite is petty (small-minded). 'Large' plays on 'magna'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-107", "question": "The idiom “to cool one's heels” means:", "options": ["To calm down after anger", "To run away quickly", "To relax after hard work", "To be kept waiting"], "answer": 3, "explanation": "To cool one's heels is to be made to wait, usually by someone more powerful. 'Calm down' is the tempting literal guess.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-108", "question": "One word for “a person whose knowledge spans many different subjects”:", "options": ["Polyglot", "Polymath", "Dilettante", "Pedant"], "answer": 1, "explanation": "A polymath has wide learning in many fields. A polyglot knows many languages; a dilettante dabbles without depth; a pedant fusses over minor rules.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-109", "question": "In the sentence “The lawyer's specious argument impressed the jury at first but collapsed under scrutiny”, the word “specious” means:", "options": ["Seemingly sound but actually false", "Specific and precise", "Rude and aggressive", "Spacious and detailed"], "answer": 0, "explanation": "Specious describes something that looks plausible but is misleading or false, which fits an argument that later collapses.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-110", "question": "The idiom “to bell the cat” means:", "options": ["To make a lot of noise", "To warn others of danger", "To undertake a risky task for the common good", "To punish a wrongdoer"], "answer": 2, "explanation": "From the fable of the mice: everyone agrees the cat should wear a bell, but no one dares to tie it. To bell the cat is to take on that dangerous job.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-111", "question": "One word for “a person who constantly and needlessly worries about his or her health”:", "options": ["Misanthrope", "Valetudinarian", "Hypocrite", "Hypochondriac"], "answer": 3, "explanation": "A hypochondriac is anxious about imagined illness. A valetudinarian is someone actually in weak health (or over-concerned with it), so hypochondriac is the precise word for needless worry; a hypocrite pretends to virtue.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-112", "question": "Choose the correctly spelt word for “an expert judge in matters of taste”.", "options": ["Connoissuer", "Conoisseur", "Connoiseur", "Connoisseur"], "answer": 3, "explanation": "Connoisseur (an expert judge of taste) has double n, double s and ends in -eur.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-vocabulary-113", "question": "Choose the antonym of “Ingenuous”.", "options": ["Frank", "Naive", "Artful", "Unintelligent"], "answer": 2, "explanation": "Ingenuous means innocent and candid, so its opposite is artful (crafty). 'Unintelligent' is the trap, treating it as ingenious (clever).", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id":"eng-vocabulary-114","question":"Choose the antonym of “Frugal”.","options":["Extravagant","Thrifty","Careful","Economical"],"answer":0,"explanation":"Frugal means sparing or economical with money; its opposite is extravagant (spending wastefully). Thrifty and economical are synonyms.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-115","question":"One word for “a person who collects postage stamps”:","options":["Numismatist","Philatelist","Cartographer","Lexicographer"],"answer":1,"explanation":"A philatelist collects or studies stamps. A numismatist collects coins, a cartographer makes maps and a lexicographer compiles dictionaries.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-116","question":"The idiom “to break the ice” means:","options":["To do something dangerous","To cause a serious quarrel","To reveal a secret","To make a start in getting people to relax and talk"],"answer":3,"explanation":"Breaking the ice is easing the initial awkwardness among people who have just met, e.g. with a joke or a game.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-117","question":"Choose the synonym of “Tenacious”.","options":["Careless","Feeble","Persistent","Hesitant"],"answer":2,"explanation":"Tenacious means holding firmly to a purpose — persistent, determined. Hesitant and feeble are nearly opposite.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-118","question":"One word for “an animal that can live both on land and in water”:","options":["Mammal","Amphibian","Reptile","Carnivore"],"answer":1,"explanation":"Amphibians (such as frogs) live both on land and in water. Reptiles, though some swim, are not defined by this.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-119","question":"The hotel offers free ___ to delegates. Choose the correctly spelt word for the blank.","options":["Accommodation","Acommodation","Accomodation","Acomodation"],"answer":0,"explanation":"'Accommodation' has double c and double m.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-120","question":"Choose the synonym of “Capricious”.","options":["Cautious","Steady","Generous","Whimsical"],"answer":3,"explanation":"Capricious means given to sudden, unaccountable changes of mood or behaviour — whimsical. Steady is its antonym.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-121","question":"Choose the antonym of “Affluent”.","options":["Prosperous","Opulent","Indigent","Influential"],"answer":2,"explanation":"Affluent means wealthy; indigent means poor and needy. Opulent and prosperous are synonyms of affluent; 'influential' merely sounds similar.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-122","question":"Choose the synonym of “Placate”.","options":["Replace","Provoke","Postpone","Pacify"],"answer":3,"explanation":"To placate is to calm someone's anger — to pacify or appease. Provoke means the opposite.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-123","question":"Choose the antonym of “Clandestine”.","options":["Covert","Secret","Open","Illegal"],"answer":2,"explanation":"Clandestine means kept secret, especially because it is illicit; its opposite is open. Secret and covert are synonyms.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-124","question":"One word for “the murder of one's own brother”:","options":["Patricide","Fratricide","Regicide","Genocide"],"answer":1,"explanation":"Fratricide is killing one's brother (Latin frater). Patricide is killing one's father, regicide a king, and genocide a whole people.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-125","question":"One word for “words inscribed on a tomb in memory of the person buried there”:","options":["Epitaph","Epigram","Epilogue","Epithet"],"answer":0,"explanation":"An epitaph is the inscription on a tomb. An epigram is a short witty saying, an epilogue a concluding section, and an epithet a descriptive name.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-126","question":"The idiom “to turn a blind eye” means:","options":["To pretend not to notice something wrong","To lose one's eyesight","To look at something angrily","To keep careful watch"],"answer":0,"explanation":"To turn a blind eye is to deliberately ignore something, usually wrongdoing, that one knows about.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-127","question":"The idiom “a white elephant” refers to:","options":["A rare and precious gift","A possession that costs much to maintain but is of little use","A powerful but gentle person","An unexpected success"],"answer":1,"explanation":"A white elephant is something expensive to keep that brings little benefit — for example, a huge stadium that is rarely used.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-128","question":"Choose the synonym of “Laudable”.","options":["Shameful","Audible","Praiseworthy","Doubtful"],"answer":2,"explanation":"Laudable means deserving praise. 'Audible' (able to be heard) is a sound-alike trap; shameful is the opposite.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-129","question":"One word for “a person who leaves his own country to settle permanently in another”:","options":["Tourist","Immigrant","Refugee","Emigrant"],"answer":3,"explanation":"From the point of view of the country he leaves, he is an emigrant (e- = out). He is an immigrant to the country he enters; a refugee flees danger or persecution.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-130","question":"Which of these four words is spelt incorrectly: Occurence, Committee, Privilege, Rhythm?","options":["Committee","Occurence","Privilege","Rhythm"],"answer":1,"explanation":"The correct spelling is 'occurrence', with double r and -ence. The other three are spelt correctly.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-131","question":"Fill in the blank with the suitable idiom: The new manager decided to ___ and confront the union leaders directly instead of avoiding the issue.","options":["pass the buck","sit on the fence","let sleeping dogs lie","take the bull by the horns"],"answer":3,"explanation":"To take the bull by the horns is to face a difficult situation boldly. Sitting on the fence and letting sleeping dogs lie both mean avoiding action; passing the buck means shifting responsibility.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-132","question":"Choose the synonym of “Fortuitous”.","options":["Carefully planned","Very fortunate","Happening by chance","Strongly defended"],"answer":2,"explanation":"Fortuitous means happening by accident or chance. It is often confused with 'fortunate', but a fortuitous event need not be lucky.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-133","question":"Choose the synonym of “Pernicious”.","options":["Harmful","Thrifty","Precise","Persistent"],"answer":0,"explanation":"Pernicious means having a harmful effect, especially gradually or subtly. 'Thrifty' might be guessed by confusing it with 'parsimonious'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-134","question":"Choose the antonym of “Spurious”.","options":["Fake","False","Genuine","Speedy"],"answer":2,"explanation":"Spurious means false or not genuine; its opposite is genuine. False and fake are synonyms.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-135","question":"Choose the antonym of “Acrimonious”.","options":["Quarrelsome","Bitter","Hostile","Amicable"],"answer":3,"explanation":"Acrimonious means bitter and angry (as in an acrimonious debate); amicable means friendly. Bitter and hostile are synonyms.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-136","question":"One word for “government by a small group of powerful people”:","options":["Monarchy","Oligarchy","Plutocracy","Theocracy"],"answer":1,"explanation":"Oligarchy is rule by a few. Plutocracy is rule by the wealthy (who may or may not be few), theocracy rule by religious authority, monarchy rule by one sovereign.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-137","question":"One word for “an extreme fear of heights”:","options":["Acrophobia","Agoraphobia","Hydrophobia","Xenophobia"],"answer":0,"explanation":"Acrophobia is fear of heights (Greek akron, peak). Agoraphobia is fear of open or crowded places, hydrophobia of water and xenophobia of foreigners.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-138","question":"The idiom “to have an axe to grind” means:","options":["To have a lot of hard work to do","To have a private, selfish motive","To be ready to fight","To complain constantly"],"answer":1,"explanation":"Someone with an axe to grind has a personal interest or grievance behind what he says or does.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-139","question":"The idiom “to rest on one's laurels” means:","options":["To be satisfied with past success and make no further effort","To retire with honour","To celebrate a victory","To take a well-deserved holiday"],"answer":0,"explanation":"Resting on one's laurels is relying on past achievements instead of continuing to work. It is usually critical, not complimentary.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-140","question":"Choose the synonym of “Querulous”.","options":["Uncertain","Inquisitive","Quarrelsome","Complaining"],"answer":3,"explanation":"Querulous means complaining in a petulant or whining way. 'Inquisitive' is suggested by 'query', and 'quarrelsome' by the sound, but neither is the meaning.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-141","question":"Which of these four words is spelt incorrectly: Embarassment, Questionnaire, Millennium, Lieutenant?","options":["Millennium","Questionnaire","Embarassment","Lieutenant"],"answer":2,"explanation":"The correct spelling is 'embarrassment', with double r and double s. The other words are spelt correctly.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-142","question":"One word for “a speech in a play in which a character, alone on stage, speaks his thoughts aloud”:","options":["Soliloquy","Monologue","Dialogue","Prologue"],"answer":0,"explanation":"A soliloquy is spoken by a character alone, to himself. A monologue is a long speech by one person that others may hear; a prologue is an introduction.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-143","question":"Choose the antonym of “Augment”.","options":["Enlarge","Diminish","Supplement","Amplify"],"answer":1,"explanation":"Augment means to increase; its opposite is diminish. Enlarge, supplement and amplify all mean adding to something.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-144","question":"Choose the synonym of “Sagacious”.","options":["Lustful","Wise","Talkative","Ferocious"],"answer":1,"explanation":"Sagacious means having keen judgement — wise, shrewd. 'Lustful' is the meaning of the look-alike 'salacious'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-145","question":"Choose the antonym of “Intrepid”.","options":["Valiant","Fearless","Daring","Timid"],"answer":3,"explanation":"Intrepid means fearless; its opposite is timid. Fearless, daring and valiant are synonyms.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-146","question":"One word for “the belief that God is present in everything in nature”:","options":["Pantheism","Polytheism","Monotheism","Atheism"],"answer":0,"explanation":"Pantheism (pan = all) identifies God with the universe and nature. Polytheism is belief in many gods, monotheism in one God, and atheism in none.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-147","question":"The idiom “to carry coals to Newcastle” means:","options":["To bring bad news to someone","To do very hard physical work","To do something unnecessary by taking a thing where it is already plentiful","To make a large profit from trade"],"answer":2,"explanation":"Newcastle was a famous coal-mining town, so carrying coal there is pointless — the idiom means a superfluous action.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-148","question":"The phrase “Hobson's choice” means:","options":["A wise choice made by an expert","A choice made after long thought","A choice between two equally good options","A situation in which there is no real choice — take what is offered or nothing"],"answer":3,"explanation":"Hobson, a stable owner, let customers take only the horse nearest the door or none at all. So 'Hobson's choice' is no choice. A choice between two unpleasant options is a 'dilemma'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-149","question":"One word for “a person who is new to a profession, subject or activity”:","options":["Veteran","Neophyte","Mentor","Charlatan"],"answer":1,"explanation":"A neophyte is a beginner or novice. A veteran is highly experienced, a mentor guides others, and a charlatan falsely claims skill.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-150","question":"Choose the synonym of “Munificent”.","options":["Municipal","Magnificent","Generous","Miserly"],"answer":2,"explanation":"Munificent means very generous in giving. 'Magnificent' is a sound-alike trap, and 'miserly' is the opposite.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-151","question":"Choose the antonym of “Esoteric”.","options":["Commonplace","Obscure","Mysterious","Arcane"],"answer":0,"explanation":"Esoteric means understood only by a small circle of specialists; commonplace (ordinary, widely known) is its opposite. Obscure and arcane are synonyms.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-152","question":"Choose the correctly spelt word: A good doctor must be ___ about following up with patients.","options":["Concientious","Consciencious","Conscientous","Conscientious"],"answer":3,"explanation":"'Conscientious' (careful and diligent) keeps 'science' inside it: con-sci-en-tious.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-153","question":"Choose the synonym of “Enervate”.","options":["Irritate","Energise","Weaken","Encourage"],"answer":2,"explanation":"Enervate means to drain of energy — to weaken. It looks like 'energise', its near opposite, which is the trap.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-154","question":"Choose the synonym of “Noisome”.","options":["Noisy","Offensive","Troublesome","Cheerful"],"answer":1,"explanation":"Noisome means offensive or disgusting, especially in smell ('a noisome drain'). It has nothing to do with noise.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-155","question":"Choose the synonym of “Restive”.","options":["Restless","Restful","Calm","Exhausted"],"answer":0,"explanation":"Restive means restless, uneasy or unwilling to be controlled ('the crowd grew restive'). 'Restful' and 'calm' are near opposites.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-156","question":"In the sentence “The enormity of the crime shocked the whole nation”, the word 'enormity' means:","options":["Long duration","Huge size","Rapid spread","Great wickedness"],"answer":3,"explanation":"In careful usage 'enormity' means extreme wickedness or seriousness. Using it for mere size ('enormousness') is the trap.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-157","question":"In the sentence “The dispute should be settled by a disinterested arbitrator”, the word 'disinterested' means:","options":["Bored","Impartial","Unqualified","Unpaid"],"answer":1,"explanation":"Disinterested means having no personal stake — impartial. 'Uninterested' means not interested or bored, which is the common confusion.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-158","question":"Choose the synonym of “Venal”.","options":["Poisonous","Pardonable","Corruptible","Sacred"],"answer":2,"explanation":"Venal means open to bribery. 'Pardonable' is the meaning of 'venial' (a venial sin), and 'poisonous' that of 'venomous'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-159","question":"Choose the antonym of “Quiescent”.","options":["Active","Dormant","Latent","Inactive"],"answer":0,"explanation":"Quiescent means in a state of inactivity or dormancy; its opposite is active. Dormant, latent and inactive are synonyms.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-160","question":"Choose the antonym of “Felicitous”.","options":["Well-chosen","Apt","Inappropriate","Fitting"],"answer":2,"explanation":"Felicitous means well-chosen or apt ('a felicitous phrase'); its opposite is inappropriate. The other three options are synonyms.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-161","question":"Choose the antonym of “Penchant”.","options":["Aversion","Liking","Inclination","Fondness"],"answer":0,"explanation":"A penchant is a strong liking or inclination; its opposite is aversion (strong dislike).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-162","question":"One word for “government by the mob”:","options":["Anarchy","Ochlocracy","Kleptocracy","Oligarchy"],"answer":1,"explanation":"Ochlocracy (Greek okhlos, mob) is mob rule. Anarchy is the absence of government, kleptocracy rule by thieves, and oligarchy rule by a few.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-163","question":"One word for “the study of ancient handwriting and manuscripts”:","options":["Orthography","Epigraphy","Calligraphy","Palaeography"],"answer":3,"explanation":"Palaeography studies old handwriting. Epigraphy studies inscriptions on stone or metal, calligraphy is the art of beautiful writing, and orthography is correct spelling.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-164","question":"One word for “an exact copy of a document, especially one showing its original appearance”:","options":["Facsimile","Forgery","Manuscript","Transcript"],"answer":0,"explanation":"A facsimile reproduces a document exactly. A transcript copies only the words; a forgery is a copy made to deceive.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-165","question":"The idiom “to cross the Rubicon” means:","options":["To betray a friend","To travel to a distant land","To overcome a minor difficulty","To take a step that cannot be reversed"],"answer":3,"explanation":"Julius Caesar's crossing of the river Rubicon in 49 BC committed him to civil war. The idiom means passing a point of no return.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-166","question":"The phrase “the sword of Damocles” refers to:","options":["A sudden, decisive victory","A weapon of great power","A constant threat of danger hanging over someone","A difficult problem solved by force"],"answer":2,"explanation":"Damocles sat beneath a sword hung by a single hair, showing the ever-present peril of a powerful position. A difficult problem solved by force is 'cutting the Gordian knot'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-167","question":"The idiom “to eat humble pie” means:","options":["To live in poverty","To admit one's mistake and apologise humbly","To eat very little","To accept a low-paid job"],"answer":1,"explanation":"Eating humble pie is being forced to admit that one was wrong, usually with humiliation.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-168","question":"Fill in the blank with the suitable phrase: Everyone expected the senior lawyers to win the debate, but the quiet first-year student turned out to be a ___ and took the trophy.","options":["white elephant","black sheep","lame duck","dark horse"],"answer":3,"explanation":"A dark horse is a little-known competitor who unexpectedly wins. A black sheep is a disgraced family member, and a lame duck an ineffective person.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-169","question":"The idiom “to draw the long bow” means:","options":["To aim at a distant target","To plan a long-term strategy","To exaggerate or tell tall stories","To show great patience"],"answer":2,"explanation":"To draw the long bow is to exaggerate. The archery image is a trap that suggests long-range aiming.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-170","question":"Choose the synonym of “Lugubrious”.","options":["Mournful","Slippery","Greedy","Talkative"],"answer":0,"explanation":"Lugubrious means looking or sounding sad and dismal. 'Slippery' would be 'lubricious', a sound-alike.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-171","question":"Choose the synonym of “Insouciant”.","options":["Insulting","Nonchalant","Anxious","Insolvent"],"answer":1,"explanation":"Insouciant means showing casual lack of concern — nonchalant, carefree. 'Anxious' is the opposite; 'insulting' and 'insolvent' are look-alike traps.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-172","question":"Choose the correctly spelt word: The new rules will ___ all earlier circulars on the subject.","options":["Superseed","Supercede","Supersede","Supperseed"],"answer":2,"explanation":"'Supersede' comes from Latin supersedere and is spelt with -sede; 'supercede' is a very common misspelling.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-vocabulary-173","question":"In the sentence “He is an inveterate liar, so do not trust his promises”, 'inveterate' means:","options":["Occasional","Habitual","Clever","Repentant"],"answer":1,"explanation":"Inveterate means having a long-established habit that is unlikely to change. 'Occasional' and 'repentant' contradict this.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"}
];

export default questions;
